from pathlib import Path
import nbformat as nbf

ROOT = Path(__file__).resolve().parent

def make_notebook(path, cells):
    notebook = nbf.v4.new_notebook()
    notebook.metadata = {"kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"}}
    notebook.cells = [nbf.v4.new_markdown_cell(text) if kind == "md" else nbf.v4.new_code_cell(text) for kind, text in cells]
    nbf.write(notebook, ROOT / path)

generator_cells = [
("md", "# SDN DDoS Dataset Generator\n\nCreates a reproducible, labeled flow-window dataset for an isolated SDN research lab. Synthetic mode is the default and never emits DDoS traffic. The canonical schema is designed to accept later Ryu/OVS telemetry."),
("md", "## Context & Methods\n\nLabels are generator ground truth, not model predictions. Each row represents one switch/source/destination/time window. Attack names describe simulated behaviors only. The optional real-lab helpers are observation-only and must run inside `wsl -d Wireless`."),
("code", """from pathlib import Path\nimport json, os, platform, sys\nimport numpy as np\nimport pandas as pd\n\nSEED = 42\nROWS_PER_CLASS = int(os.getenv('SDN_DDOS_ROWS_PER_CLASS', '500'))\nWINDOW_SECONDS = 10\nOUTPUT_DIR = Path(os.getenv('SDN_DDOS_OUTPUT_DIR', './artifacts')).expanduser().resolve()\nOUTPUT_DIR.mkdir(parents=True, exist_ok=True)\nCLASSES = ['BENIGN','UDP_FLOOD','ICMP_FLOOD','UDP_AMPLIFICATION','SYN_FLOOD','PING_OF_DEATH_STYLE','SMURF_STYLE','HTTP_FLOOD','SLOWLORIS_STYLE','LAND_STYLE','PACKET_IN_FLOOD']\nPROFILES = {\n'BENIGN':('BENIGN',['TCP','UDP','ICMP'],(30,180),(400,1200),(1,8),(5,25)),\n'UDP_FLOOD':('VOLUMETRIC',['UDP'],(2500,12000),(256,900),(30,250),(25,75)),\n'ICMP_FLOOD':('VOLUMETRIC',['ICMP'],(2000,10000),(64,1200),(10,100),(20,65)),\n'UDP_AMPLIFICATION':('VOLUMETRIC',['UDP'],(5000,22000),(700,1400),(20,180),(35,90)),\n'SYN_FLOOD':('PROTOCOL',['TCP'],(1200,9000),(40,100),(100,1200),(40,95)),\n'PING_OF_DEATH_STYLE':('PROTOCOL',['ICMP'],(100,900),(1400,9000),(5,60),(15,55)),\n'SMURF_STYLE':('PROTOCOL',['ICMP'],(1500,9000),(800,1500),(30,250),(30,85)),\n'HTTP_FLOOD':('APPLICATION',['TCP'],(500,5000),(300,1400),(50,700),(25,80)),\n'SLOWLORIS_STYLE':('APPLICATION',['TCP'],(10,120),(50,400),(80,900),(20,70)),\n'LAND_STYLE':('PROTOCOL',['TCP'],(100,1500),(40,800),(10,150),(20,70)),\n'PACKET_IN_FLOOD':('SDN_CONTROL',['TCP','UDP'],(300,3500),(60,600),(300,2500),(60,100)),}\nprint({'python':sys.version.split()[0], 'platform':platform.platform(), 'output':str(OUTPUT_DIR)})"""),
("md", "## Generate and validate canonical records"),
("code", """rng = np.random.default_rng(SEED)\nrows = []\nfor class_index, label in enumerate(CLASSES):\n    family, protocols, pps_range, size_range, flow_range, cpu_range = PROFILES[label]\n    for row_index in range(ROWS_PER_CLASS):\n        pps = float(rng.uniform(*pps_range)); packet_size = float(rng.uniform(*size_range))\n        packets = max(1, int(pps * WINDOW_SECONDS * rng.uniform(.9, 1.1)))\n        flows = max(1, int(rng.uniform(*flow_range))); protocol = rng.choice(protocols)\n        syn = int(packets * rng.uniform(.55, .98)) if protocol == 'TCP' else 0\n        ack_factor = rng.uniform(.01, .25) if label in {'SYN_FLOOD','SLOWLORIS_STYLE'} else rng.uniform(.55,.99)\n        ack = int(syn * ack_factor); completion = ack / max(syn, 1)\n        churn = max(1, int(flows * rng.uniform(.8, 2.0)))\n        rows.append({'timestamp':(pd.Timestamp.now(tz='UTC').floor('s') + pd.Timedelta(seconds=(class_index*ROWS_PER_CLASS+row_index)*WINDOW_SECONDS)).isoformat(),'experiment_id':'synthetic_baseline_v1','scenario_id':f'scn_{class_index:02d}_{row_index:05d}','switch_id':rng.choice(['s1','s2','s3']),'src_ip':f'10.0.{rng.integers(1,20)}.{rng.integers(1,255)}','dst_ip':f'10.0.0.{rng.integers(1,10)}','src_port':int(rng.integers(1024,65535)),'dst_port':int(rng.choice([53,80,443,22,123,8080])),'protocol':protocol,'application':'HTTP' if protocol=='TCP' else protocol,'window_seconds':WINDOW_SECONDS,'packet_count':packets,'byte_count':int(packets*packet_size),'flow_count':flows,'packet_rate':packets/WINDOW_SECONDS,'byte_rate':packets*packet_size/WINDOW_SECONDS,'flow_rate':flows/WINDOW_SECONDS,'mean_packet_size':packet_size,'inter_arrival_mean_ms':1000/max(pps,1),'inter_arrival_std_ms':1000/max(pps,1)*rng.uniform(.05,.8),'tcp_syn_count':syn,'tcp_ack_count':ack,'tcp_fin_count':int(ack*rng.uniform(.05,.7)),'tcp_rst_count':int(syn*rng.uniform(.01,.25)),'tcp_handshake_completion_ratio':completion,'unique_dst_ports':churn,'unique_dst_ips':max(1,int(churn*.4)),'src_entropy':rng.uniform(.05,.95),'dst_entropy':rng.uniform(.05,.95),'flow_table_size':int(np.clip(30+churn,1,10000)),'flow_table_utilization':float(np.clip((30+churn)/1000,0,1)),'packet_in_count':int(churn*rng.uniform(.2,1.5)),'flow_mod_count':int(churn*rng.uniform(.1,1.1)),'controller_cpu_pct':float(np.clip(rng.uniform(*cpu_range),0,100)),'controller_rx_kbps':packets*packet_size*8/1000/WINDOW_SECONDS,'port_rx_packets':packets,'port_tx_packets':int(packets*rng.uniform(.1,.95)),'port_rx_dropped':int(packets*rng.uniform(0,.02 if label=='BENIGN' else .2)),'port_tx_dropped':int(packets*rng.uniform(0,.02 if label=='BENIGN' else .2)),'attack_intensity':0.0 if label=='BENIGN' else rng.uniform(.35,1.0),'attacker_count':int(rng.integers(1,4 if label=='BENIGN' else 20)),'background_traffic_level':rng.uniform(.1,.6),'label':label,'attack_family':family,'data_source':'synthetic'})\ndataset = pd.DataFrame(rows)\nrequired = {'label','timestamp','packet_rate','byte_rate','flow_rate','tcp_handshake_completion_ratio','controller_cpu_pct','data_source'}\nassert required <= set(dataset.columns)\nassert dataset['label'].isin(CLASSES).all()\nassert dataset['packet_rate'].ge(0).all() and dataset['tcp_handshake_completion_ratio'].between(0,1).all()\nassert dataset.duplicated().sum() == 0\nprint(dataset.shape); display(dataset.head(3)); print(dataset['label'].value_counts())"""),
("md", "## Export\n\nCSV is always written. Parquet is attempted for Spark performance and gracefully skipped if no Parquet engine is installed."),
("code", """csv_path = OUTPUT_DIR / 'master_sdn_ddos_dataset.csv'; parquet_path = OUTPUT_DIR / 'master_sdn_ddos_dataset.parquet'\ndataset.to_csv(csv_path, index=False)\ntry:\n    dataset.to_parquet(parquet_path, index=False); parquet_status = str(parquet_path)\nexcept (ImportError, ModuleNotFoundError) as exc:\n    parquet_status = f'skipped: {exc}'\nmetadata = {'seed':SEED,'rows':len(dataset),'columns':len(dataset.columns),'labels':CLASSES,'parquet':parquet_status,'unit':'switch/source/destination/time window','notes':'Synthetic behavioral proxies; validate final claims with isolated real-lab telemetry.'}\n(OUTPUT_DIR/'master_sdn_ddos_dataset_metadata.json').write_text(json.dumps(metadata, indent=2, default=str), encoding='utf-8')\n(OUTPUT_DIR/'feature_dictionary.json').write_text(json.dumps({'target':'label','categorical':['timestamp','experiment_id','scenario_id','switch_id','src_ip','dst_ip','protocol','application','label','attack_family','data_source'],'data_source_values':['synthetic','real_lab']}, indent=2), encoding='utf-8')\nprint({'csv':str(csv_path),'parquet':parquet_status})"""),
("md", "## Optional real-lab path\n\nRun only inside `wsl -d Wireless`: `python real_lab/collect_ovs_telemetry.py --once`. The helper reads existing OVS counters and does not create traffic, install flows, or contact external hosts. `real_lab/mininet_topology.py` starts a small isolated topology and performs only `pingAll()`."),
("code", "print('Synthetic generation complete. The optional lab helpers are observation-only.')"),
("md", "## Takeaways\n\nThe dataset is balanced by construction, carries explicit scenario metadata, and contains both flow-level and SDN-control-plane features. Synthetic data is a reproducible development baseline, not evidence of real-world prevalence or detector accuracy."),]

analytics_cells = [
("md", "# PySpark SDN DDoS Analytics\n\nLoads notebook 01 output, cleans it, preprocesses numeric features with Spark ML, and creates five Plotly visualizations with explicit inferences."),
("md", "## Context & Methods\n\nThe label is excluded from features. Identifiers are retained for auditability but are not predictive inputs. Aggregated/sample data is converted to pandas only for bounded Plotly rendering."),
("code", """import os\nfrom pathlib import Path\nfrom pyspark.sql import SparkSession, functions as F\nfrom pyspark.ml import Pipeline\nfrom pyspark.ml.feature import VectorAssembler, StandardScaler\n\ninput_path = Path(os.getenv('SDN_DDOS_INPUT_PATH','./artifacts/master_sdn_ddos_dataset.parquet'))\nif not input_path.exists() and input_path.with_suffix('.csv').exists(): input_path = input_path.with_suffix('.csv')\nif not input_path.exists(): raise FileNotFoundError(f'Run notebook 01 first; missing {input_path}')\nspark = SparkSession.builder.appName('SDN-DDoS-Analytics').master(os.getenv('SPARK_MASTER','local[*]')).getOrCreate()\nspark.sparkContext.setLogLevel('WARN')\nraw_df = spark.read.parquet(str(input_path)) if input_path.suffix=='.parquet' else spark.read.option('header',True).option('inferSchema',True).csv(str(input_path))\nprint(input_path, raw_df.count(), len(raw_df.columns)); raw_df.printSchema()"""),
("md", "## Clean and validate"),
("code", """numeric_columns = ['window_seconds','src_port','dst_port','packet_count','byte_count','flow_count','packet_rate','byte_rate','flow_rate','mean_packet_size','inter_arrival_mean_ms','inter_arrival_std_ms','tcp_syn_count','tcp_ack_count','tcp_fin_count','tcp_rst_count','tcp_handshake_completion_ratio','unique_dst_ports','unique_dst_ips','src_entropy','dst_entropy','flow_table_size','flow_table_utilization','packet_in_count','flow_mod_count','controller_cpu_pct','controller_rx_kbps','port_rx_packets','port_tx_packets','port_rx_dropped','port_tx_dropped','attack_intensity','attacker_count','background_traffic_level']\nclean_df = raw_df\nfor name in numeric_columns: clean_df = clean_df.withColumn(name,F.col(name).cast('double'))\nclean_df = clean_df.dropDuplicates().filter((F.col('packet_rate')>=0)&(F.col('byte_rate')>=0)&(F.col('flow_rate')>=0)&F.col('tcp_handshake_completion_ratio').between(0,1)).fillna(0.0, subset=numeric_columns)\nprint('clean rows:',clean_df.count()); clean_df.groupBy('label').count().orderBy('label').show()"""),
("md", "## Spark ML preprocessing"),
("code", """feature_columns = ['packet_count','byte_count','flow_count','packet_rate','byte_rate','flow_rate','mean_packet_size','inter_arrival_mean_ms','inter_arrival_std_ms','tcp_syn_count','tcp_ack_count','tcp_fin_count','tcp_rst_count','tcp_handshake_completion_ratio','unique_dst_ports','unique_dst_ips','src_entropy','dst_entropy','flow_table_size','flow_table_utilization','packet_in_count','flow_mod_count','controller_cpu_pct','controller_rx_kbps','port_rx_packets','port_tx_packets','port_rx_dropped','port_tx_dropped','attack_intensity','attacker_count','background_traffic_level']\npreprocess = Pipeline(stages=[VectorAssembler(inputCols=feature_columns,outputCol='features_raw',handleInvalid='keep'),StandardScaler(inputCol='features_raw',outputCol='features_scaled',withMean=False,withStd=True)])\nprocessed_df = preprocess.fit(clean_df).transform(clean_df).cache(); print('processed:',processed_df.count(),'features:',len(feature_columns))"""),
("md", "## Plotly data extracts"),
("code", """import plotly.express as px\nlabel_counts = clean_df.groupBy('label').count().toPandas()\nplot_df = clean_df.select('label','attack_family','packet_rate','byte_rate','tcp_handshake_completion_ratio','controller_cpu_pct','packet_in_count','flow_table_size').limit(10000).toPandas()\nsummary = clean_df.groupBy('label').agg(F.avg('packet_rate').alias('mean_packet_rate'),F.avg('byte_rate').alias('mean_byte_rate'),F.avg('tcp_handshake_completion_ratio').alias('mean_completion'),F.avg('controller_cpu_pct').alias('mean_controller_cpu')).orderBy('label').toPandas(); print(summary.to_string(index=False))"""),
("md", "## 1. Class distribution\n\n**Inference:** controlled class balance supports comparison across scenarios; real deployments should report prevalence separately."),
("code", "fig=px.bar(label_counts,x='label',y='count',color='label',title='Records by Ground-Truth Class'); fig.update_layout(showlegend=False,xaxis_tickangle=-35); fig.show()"),
("md", "## 2. Packet rate\n\n**Inference:** volumetric and packet-in scenarios should be higher than benign; slow-rate behavior shows why a single threshold is inadequate."),
("code", "fig=px.box(plot_df,x='label',y='packet_rate',color='attack_family',points=False,title='Packet Rate by Scenario'); fig.update_layout(xaxis_tickangle=-35); fig.show()"),
("md", "## 3. Packet rate vs byte rate\n\n**Inference:** the relationship distinguishes small-packet volume from large-payload behavior such as amplification-style or oversized-packet simulations."),
("code", "fig=px.scatter(plot_df,x='packet_rate',y='byte_rate',color='label',hover_data=['attack_family'],title='Packet Rate vs Byte Rate'); fig.show()"),
("md", "## 4. TCP completion ratio\n\n**Inference:** SYN flood and slow-rate scenarios should have lower completion than ordinary TCP. Non-TCP zeroes are not failed TCP handshakes."),
("code", "tcp_plot=plot_df[plot_df.label.isin(['BENIGN','SYN_FLOOD','HTTP_FLOOD','SLOWLORIS_STYLE','LAND_STYLE'])]; fig=px.violin(tcp_plot,x='label',y='tcp_handshake_completion_ratio',color='label',box=True,points=False,title='TCP Handshake Completion Ratio'); fig.show()"),
("md", "## 5. SDN controller pressure\n\n**Inference:** packet-in activity and flow-table size provide SDN-specific evidence of control-plane pressure."),
("code", "fig=px.scatter(plot_df,x='packet_in_count',y='controller_cpu_pct',color='label',size='flow_table_size',title='Packet-In Activity vs Controller CPU Proxy'); fig.show()"),
("md", "## Takeaways\n\nThe clean Spark DataFrame and scaled feature vector are ready for downstream modeling. These patterns are synthetic proxies; rerun with `data_source = real_lab` before making real-world performance claims."),
("code", "print('Analytics complete.'); spark.stop()"),]

make_notebook('01_SDN_DDoS_Dataset_Generator.ipynb', generator_cells)
